<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { request } from '@/services/http'
import { hydrateFinanceSettings } from '@/services/financeSettings'
import { canViewFobCoefficient, fobClassifications } from '@/services/fobClassification'
const values=ref<Record<string,number>>({}), version=ref(-1), loading=ref(true), busy=ref(false), message=ref(''), error=ref('')
async function load(){loading.value=true;error.value='';try{const data=await request<{value:Record<string,number>;_version:number}>('/finance-settings/fob-pricing');values.value={...data.value};version.value=data._version}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(()=>{if(canViewFobCoefficient.value)void load()})
async function save(){if(busy.value)return;error.value='';message.value='';if(fobClassifications.some(c=>!Number.isFinite(values.value[c.value])||values.value[c.value]!<=0||values.value[c.value]!>10)){error.value='三类系数均须大于0且不超过10';return}busy.value=true;try{const result=await request<{value:Record<string,number>;_version:number}>('/finance-settings/fob-pricing',{method:'PUT',headers:{'If-Match':String(version.value)},body:JSON.stringify(values.value)});values.value={...result.value};version.value=result._version;message.value='FOB 系数已保存，仅影响新报价及主动重新报价';try{await hydrateFinanceSettings({force:true})}catch{error.value='系数已保存，页面缓存刷新失败，请刷新页面后报价'}}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><section v-if="canViewFobCoefficient" class="fob-settings"><header><div><b>FOB 报价分类系数</b><p>单条与批量 FOB 报价共用；仅管理员可查看及设置系数。</p></div><button :disabled="loading||busy||!Object.keys(values).length" @click="save">{{busy?'正在保存…':'保存 FOB 系数'}}</button></header><p v-if="loading">正在读取系数…</p><div v-else class="factor-grid"><label v-for="c in fobClassifications" :key="c.value"><strong>{{c.label}}</strong><span>报价系数</span><input v-model.number="values[c.value]" :aria-label="c.label+'系数'" type="number" min="0.000001" max="10" step="0.01" :disabled="busy"><small>{{c.special?'按实际专票类型与票点计算，缺资料持续提醒':'普票、无票等按普通报价系数计算'}}</small></label></div><p class="info">前两类按“阶梯原价 ×（1＋实际票点）”计算；新采购与原FOB缺票类型或票点时默认10点并持续提醒采购补齐对应来源SKU。已含票阶梯不重复加点；缺价或含票价与实际票点冲突时拦截。批量报价支持复制、修改或移除异常 SKU，有效商品继续报价。</p><p>系数修改仅用于新报价及主动再次发起，已保存报价保留原快照。</p><p v-if="message" role="status">{{message}}</p><p v-if="error" class="error" role="alert">{{error}} <button :disabled="busy" @click="load">重新读取</button></p></section></template>
<style scoped>
.fob-settings{padding:22px;color:#233442}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}p,small{font-size:12px;color:#7f8992;line-height:1.8}header p{margin:5px 0}.factor-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.factor-grid label{display:grid;grid-template-columns:1fr auto;gap:10px;padding:16px;background:#fafbfc;border:1px solid #dde4e8;border-radius:8px}.factor-grid strong{font-size:15px}.factor-grid span{font-size:12px;color:#7f8992}.factor-grid input{grid-column:1/-1;width:100%;box-sizing:border-box;height:40px;border:1px solid #d9e0e5;border-radius:6px;padding:0 10px;font-size:16px;font-weight:700}.factor-grid small{grid-column:1/-1}button{padding:11px 18px;background:#ff9810;border:0;border-radius:7px;font-weight:700;cursor:pointer}button:disabled{opacity:.5}.info{padding:14px 16px;background:#f5f8fb;border:1px solid #dce5ee;border-radius:7px}.error{color:#b73126}@media(max-width:900px){.factor-grid{grid-template-columns:1fr}}
</style>
